      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not specify how studies were grouped for synthesis (e.g., by intervention type, outcome, or study design) or link these groups to the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "NOT_APPLICABLE",
